// Creation bytecode of two test-only contracts used by the ERC-7540
// integration tests: MockShare (an ERC-7575 share token anyone can mint/burn)
// and MockERC7540 (an asynchronous vault with 1:1 price, controller-keyed
// requests and public fulfillDeposit/fulfillRedeem hooks standing in for the
// off-chain fulfillment actor).
//
// Compiled with forge 1.5.1 (solc 0.8.26, optimizer on, 200 runs) from the
// source below:
//
/*
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/// Test-only ERC-20 + ERC-7575 share token. Anyone can mint/burn/setVault.
contract MockShare {
    string public constant name = "Mock 7575 Share";
    string public constant symbol = "mSHARE";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => address) public vault; // ERC-7575: asset => vault entry point

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event VaultUpdate(address indexed asset, address vault);

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function burnFrom(address from, uint256 amount) external {
        balanceOf[from] -= amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
    }

    function setVault(address asset, address vault_) external {
        vault[asset] = vault_;
        emit VaultUpdate(asset, vault_);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (msg.sender != from) allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7 || interfaceId == 0xf815c03d;
    }
}

/// Test-only ERC-7540 asynchronous vault with an external ERC-7575 share
/// token, 1:1 asset/share price and controller-keyed requests (requestId is
/// always 0). Fulfillment is a public test hook (fulfillDeposit/fulfillRedeem)
/// standing in for the off-chain actor.
contract MockERC7540 {
    IERC20 private immutable _asset;
    MockShare private immutable _share;

    mapping(address => uint256) private pendingDeposit; // controller => assets
    mapping(address => uint256) private claimableDeposit; // controller => assets
    mapping(address => uint256) private pendingRedeem; // controller => shares
    mapping(address => uint256) private claimableRedeem; // controller => shares
    mapping(address => mapping(address => bool)) private operators;

    event DepositRequest(
        address indexed controller, address indexed owner, uint256 indexed requestId, address sender, uint256 assets
    );
    event RedeemRequest(
        address indexed controller, address indexed owner, uint256 indexed requestId, address sender, uint256 shares
    );
    event OperatorSet(address indexed controller, address indexed operator, bool approved);
    event Deposit(address indexed sender, address indexed owner, uint256 assets, uint256 shares);
    event Withdraw(
        address indexed sender, address indexed receiver, address indexed owner, uint256 assets, uint256 shares
    );

    constructor(address asset_, address share_) {
        _asset = IERC20(asset_);
        _share = MockShare(share_);
    }

    // --- ERC-4626/7575 metadata ---

    function asset() external view returns (address) {
        return address(_asset);
    }

    function share() external view returns (address) {
        return address(_share);
    }

    function totalAssets() external view returns (uint256) {
        return _asset.balanceOf(address(this));
    }

    function convertToShares(uint256 assets) external pure returns (uint256) {
        return assets;
    }

    function convertToAssets(uint256 shares) external pure returns (uint256) {
        return shares;
    }

    // --- ERC-7540 requests ---

    function requestDeposit(uint256 assets, address controller, address owner) external returns (uint256) {
        require(owner == msg.sender || operators[owner][msg.sender], "not owner or operator");
        require(_asset.transferFrom(owner, address(this), assets), "transferFrom failed");
        pendingDeposit[controller] += assets;
        emit DepositRequest(controller, owner, 0, msg.sender, assets);
        return 0;
    }

    function requestRedeem(uint256 shares, address controller, address owner) external returns (uint256) {
        require(owner == msg.sender || operators[owner][msg.sender], "not owner or operator");
        _share.burnFrom(owner, shares);
        pendingRedeem[controller] += shares;
        emit RedeemRequest(controller, owner, 0, msg.sender, shares);
        return 0;
    }

    function fulfillDeposit(address controller) external {
        claimableDeposit[controller] += pendingDeposit[controller];
        pendingDeposit[controller] = 0;
    }

    function fulfillRedeem(address controller) external {
        claimableRedeem[controller] += pendingRedeem[controller];
        pendingRedeem[controller] = 0;
    }

    function pendingDepositRequest(uint256, address controller) external view returns (uint256) {
        return pendingDeposit[controller];
    }

    function claimableDepositRequest(uint256, address controller) external view returns (uint256) {
        return claimableDeposit[controller];
    }

    function pendingRedeemRequest(uint256, address controller) external view returns (uint256) {
        return pendingRedeem[controller];
    }

    function claimableRedeemRequest(uint256, address controller) external view returns (uint256) {
        return claimableRedeem[controller];
    }

    // --- ERC-7540 operators ---

    function setOperator(address operator, bool approved) external returns (bool) {
        operators[msg.sender][operator] = approved;
        emit OperatorSet(msg.sender, operator, approved);
        return true;
    }

    function isOperator(address controller, address operator) external view returns (bool) {
        return operators[controller][operator];
    }

    // --- claims (7540 overloads; 1:1 price) ---

    modifier onlyControllerOrOperator(address controller) {
        require(msg.sender == controller || operators[controller][msg.sender], "not controller or operator");
        _;
    }

    function deposit(uint256 assets, address receiver, address controller)
        external
        onlyControllerOrOperator(controller)
        returns (uint256)
    {
        claimableDeposit[controller] -= assets;
        _share.mint(receiver, assets);
        emit Deposit(msg.sender, receiver, assets, assets);
        return assets;
    }

    function mint(uint256 shares, address receiver, address controller)
        external
        onlyControllerOrOperator(controller)
        returns (uint256)
    {
        claimableDeposit[controller] -= shares;
        _share.mint(receiver, shares);
        emit Deposit(msg.sender, receiver, shares, shares);
        return shares;
    }

    function redeem(uint256 shares, address receiver, address controller)
        external
        onlyControllerOrOperator(controller)
        returns (uint256)
    {
        claimableRedeem[controller] -= shares;
        require(_asset.transfer(receiver, shares), "transfer failed");
        emit Withdraw(msg.sender, receiver, controller, shares, shares);
        return shares;
    }

    function withdraw(uint256 assets, address receiver, address controller)
        external
        onlyControllerOrOperator(controller)
        returns (uint256)
    {
        claimableRedeem[controller] -= assets;
        require(_asset.transfer(receiver, assets), "transfer failed");
        emit Withdraw(msg.sender, receiver, controller, assets, assets);
        return assets;
    }

    // --- ERC-7540 claimable limits ---

    function maxDeposit(address controller) external view returns (uint256) {
        return claimableDeposit[controller];
    }

    function maxMint(address controller) external view returns (uint256) {
        return claimableDeposit[controller];
    }

    function maxWithdraw(address controller) external view returns (uint256) {
        return claimableRedeem[controller];
    }

    function maxRedeem(address controller) external view returns (uint256) {
        return claimableRedeem[controller];
    }

    // --- previews revert, per ERC-7540 ---

    function previewDeposit(uint256) external pure returns (uint256) {
        revert("ERC7540: preview not supported");
    }

    function previewMint(uint256) external pure returns (uint256) {
        revert("ERC7540: preview not supported");
    }

    function previewRedeem(uint256) external pure returns (uint256) {
        revert("ERC7540: preview not supported");
    }

    function previewWithdraw(uint256) external pure returns (uint256) {
        revert("ERC7540: preview not supported");
    }

    // --- ERC-165 ---

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7 // ERC-165
            || interfaceId == 0xe3bc4e65 // ERC-7540 operator methods
            || interfaceId == 0xce3bbe50 // ERC-7540 async deposit
            || interfaceId == 0x620ee8e4 // ERC-7540 async redeem
            || interfaceId == 0x2f0a18c5; // ERC-7575 vault
    }
}
*/

